```js
export function step(state, dt) {
  const { ball } = state;
  let remaining = dt;
  while (remaining > 0) {
    const speed = Math.hypot(ball.vx, ball.vy) || 1;
    const h = Math.min(remaining, SUBSTEP / speed);
    remaining -= h;
    if (moveAndCollide(state, h)) return true;
  }
  return false;
}
```

