4. `moveAndCollide(state, h)` — the former step body minus the outer structure:

```js
function moveAndCollide(state, h) {
  const { ball, paddle } = state;

  ball.x += ball.vx * h;
  ball.y += ball.vy * h;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Bricks
  bounceBricks(state);

  // Exit through the bottom: ball lost
  return ball.y - ball.r > HEIGHT;
}
```

5. `bounceBricks`:

```js
export function bounceBricks(state) {
  const { ball } = state;
  const touched = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) touched.push(brick);
  }
  if (touched.length === 0) return false;

  // Union box of every touched brick: adjacent bricks of a seam form a single
  // surface, so the ball bounces once instead of re-inverting on each one.
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const brick of touched) {
    minX = Math.min(minX, brick.x);
    minY = Math.min(minY, brick.y);
    maxX = Math.max(maxX, brick.x + brick.w);
    maxY = Math.max(maxY, brick.y + brick.h);
  }

  for (const brick of touched) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  const overlapLeft = ball.x + ball.r - minX;
  const overlapRight = maxX - (ball.x - ball.r);
  const overlapTop = ball.y + ball.r - minY;
  const overlapBottom = maxY - (ball.y - ball.r);
  const penX = Math.min(overlapLeft, overlapRight);
  const penY = Math.min(overlapTop, overlapBottom);

  const corner = penX === penY;
  if (corner || penX < penY) {
    if (overlapLeft < overlapRight) {
      ball.x = minX - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = maxX + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  }
  if (corner || penY < penX) {
    if (overlapTop < overlapBottom) {
      ball.y = minY - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = maxY + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
  return true;
}
```

