// --- Brick collision: "the ball plows through bricks instead of bouncing" --
// (see neon.js BUG #1). Decomposed into: no bounce at all (D1), scoring in the
// render loop instead of the physics (D8), sticky re-inversion (D2), seam
// double inversion (D3), face-vs-corner (D4), discrete tunneling at the max
// step (D5), paddle tunneling (D6), frame-rate dependence (D7).

test('D1: ball descending onto a brick bounces back up (no plow-through)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // row 0, col 0: x 4..76, y 48..68
  state.ball = { x: 40, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60); // the ball moves ~5px down, into the brick
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.ok(state.ball.vy < 0, 'vy flips upward after a top hit');
});

test('D8: a brick is destroyed and scored exactly once', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const score0 = state.score;
  state.ball = { x: 40, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(state.combo, 1);
  assert.equal(state.score - score0, scoreForBrick(brick, 1));
  // The dead brick must never be re-hit, re-scored or re-comboed.
  step(state, 1 / 60);
  assert.equal(state.score - score0, scoreForBrick(brick, 1));
  assert.equal(state.combo, 1);
});

