edits.newText:
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves the ball against every live brick it overlaps: the brick dies and
// scores, and the ball bounces. Called once per collision substep from
// step(); the render loop no longer touches brick logic.
// Returns true if at least one brick was hit.
export function bounceBricks(state) {
  const { ball } = state;
  let bounced = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    ball.vy = -Math.abs(ball.vy);
    bounced = true;
  }
  return bounced;
}

