// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (via bounceBricks).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball } = state;
  let remaining = dt;
  while (remaining > 0) {
    const speed = Math.hypot(ball.vx, ball.vy) || 1;
    const h = Math.min(remaining, SUBSTEP / speed);
    remaining -= h;
    if (moveAndCollide(state, h)) return true;
  }
  return false;
}

// One collision substep: move the ball by `h` seconds, then bounce off the
// walls, the ceiling, the paddle and the bricks. True if the ball is lost.
function moveAndCollide(state, h) {
  const { ball, paddle } = state;

  ball.x += ball.vx * h;
  ball.y += ball.vy * h;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  bounceBricks(state);

  // Exit through the bottom: ball lost
  return ball.y - ball.r > HEIGHT;
}

