test('D8: a brick is destroyed and scored exactly once', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const score0 = state.score;
  state.ball = { x: 40, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(state.combo, 1);
  assert.equal(state.score - score0, scoreForBrick(brick, 1));
  // The dead brick must never be re-hit, re-scored or re-comboed.
  step(state, 1 / 60);
  assert.equal(state.score - score0, scoreForBrick(brick, 1));
  assert.equal(state.combo, 1);
});

test('D2: ball is pushed out of the brick (no sticky re-inversion)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball drifting down slowly, already deep inside the brick: without a
  // push-out it stays overlapping and re-inverts on every step.
  state.ball = { x: 40, y: brick.y + 2, r: BALL_R, vx: 0, vy: 30 };
  bounceBricks(state);
  assert.ok(state.ball.vy < 0, 'vy flips upward');
  assert.ok(!collides(state.ball, brick), 'the ball leaves the brick');
  const vyAfter = state.ball.vy;
  step(state, 1 / 60);
  step(state, 1 / 60);
  assert.equal(state.ball.vy, vyAfter, 'vy is not re-inverted while leaving');
});

