edits.newText:
export function bounceBricks(state) {
  const { ball } = state;
  let bounced = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    // Push the ball out of the brick along y, then flip vy, so the next pass
    // does not find the ball overlapping again (no sticky re-inversion).
    const penTop = ball.y + ball.r - brick.y;
    const penBottom = brick.y + brick.h - (ball.y - ball.r);
    if (penTop < penBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
    bounced = true;
  }
  return bounced;
}

