test('D2: ball is pushed out of the brick (no sticky re-inversion)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball drifting down slowly, already deep inside the brick: without a
  // push-out it stays overlapping and re-inverts on every step.
  state.ball = { x: 40, y: brick.y + 2, r: BALL_R, vx: 0, vy: 30 };
  bounceBricks(state);
  assert.ok(state.ball.vy < 0, 'vy flips upward');
  assert.ok(!collides(state.ball, brick), 'the ball leaves the brick');
  const vyAfter = state.ball.vy;
  step(state, 1 / 60);
  step(state, 1 / 60);
  assert.equal(state.ball.vy, vyAfter, 'vy is not re-inverted while leaving');
});

test('D3: seam between two bricks — one bounce, both destroyed', () => {
  const state = createState(1);
  const a = state.bricks[0]; // col 0: x 4..76
  const b = state.bricks[1]; // col 1: x 84..156
  // Ball centered on the 8px seam (a and b are 8px apart), descending onto
  // both tops at once: the seam must behave as one surface, one bounce only.
  state.ball = { x: (a.x + a.w + b.x) / 2, y: a.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(a.alive, false);
  assert.equal(b.alive, false, 'both bricks of the seam are destroyed');
  assert.ok(state.ball.vy < 0, 'vy flips exactly once (no double inversion)');
  assert.ok(state.ball.y + state.ball.r <= a.y, 'ball ends above the seam');
});

test('D4a: side hit flips vx only', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball entering the brick through its left face (3px penetration).
  state.ball = { x: brick.x - BALL_R + 3, y: brick.y + brick.h / 2, r: BALL_R, vx: 300, vy: 100 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx flips left on a side hit');
  assert.equal(state.ball.vy, 100, 'vy is untouched by a side hit');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball is pushed out of the left face');
});

test('D4b: corner hit with equal penetration flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // 4px into the left face AND 4px into the top face: equal penetration.
  state.ball = { x: brick.x - BALL_R + 4, y: brick.y - BALL_R + 4, r: BALL_R, vx: 300, vy: 300 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components invert at a corner');
  assert.ok(
    state.ball.x + state.ball.r <= brick.x && state.ball.y + state.ball.r <= brick.y,
    'ball is pushed out to the corner',
  );
});

