edits.newText:
test('D4b: corner hit with equal penetration flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // 4px into the left face AND 4px into the top face: equal penetration.
  state.ball = { x: brick.x - BALL_R + 4, y: brick.y - BALL_R + 4, r: BALL_R, vx: 300, vy: 300 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components invert at a corner');
  assert.ok(
    state.ball.x + state.ball.r <= brick.x && state.ball.y + state.ball.r <= brick.y,
    'ball is pushed out to the corner',
  );
});

test('D5: no tunneling through a brick at the max step (level 6)', () => {
  // Max step at level 6: ballSpeed(6) * 0.05 = 35.5px, wider than the
  // crossing distance BRICK_H + 2*BALL_R = 34px: a single discrete step could
  // skip the brick entirely. The ball must still bounce.
  const state = createState(6);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the brick is hit, not skipped');
  assert.ok(state.ball.vy < 0, 'the ball bounces back up');
});

test('D6: no tunneling through the paddle at the max step (level 2)', () => {
  // The capture band is PADDLE_H = 12px wide; a max step of
  // ballSpeed(2) * 0.05 = 17.5px can jump the ball bottom edge clean over it.
  const state = createState(2);
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(2) };
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'the ball bounces off the paddle instead of falling through');
  assert.ok(state.ball.vy < 0, 'vy flips upward after the paddle bounce');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, 'the ball exits from the top of the paddle');
});

test('D7: bounce outcome is the same at 60 fps and at 20 fps', () => {
  const run = (dt) => {
    const state = createState(6);
    const brick = state.bricks[0];
    state.ball = { x: 40, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
    return { lost: step(state, dt), brickAlive: brick.alive, ballUp: state.ball.vy < 0 };
  };
  assert.deepEqual(run(1 / 60), { lost: false, brickAlive: false, ballUp: true });
  assert.deepEqual(run(0.05), { lost: false, brickAlive: false, ballUp: true });
});

